// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        _mint(address(this), 100 ether);
        _approve(address(this), address(c), 100 ether);
        c.stake(10 ether);
        uint256 supply = c.totalSupply();
        assertTrue(supply == 10 ether, "totalSupply should be 10 ether");
    }

    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    function _mint(address to, uint256 amount) internal { _balances[to] += amount; }
    function _approve(address owner, address spender, uint256 amount) internal { _allowances[owner][spender] = amount; }
    function totalSupply() external view returns (uint256) { return _balances[address(this)] + _balances[address(c)]; }
    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }
    function transfer(address to, uint256 amount) external returns (bool) { _balances[msg.sender] -= amount; _balances[to] += amount; return true; }
    function allowance(address owner, address spender) external view returns (uint256) { return _allowances[owner][spender]; }
    function approve(address spender, uint256 amount) external returns (bool) { _allowances[msg.sender][spender] = amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) { _balances[from] -= amount; _balances[to] += amount; _allowances[from][msg.sender] -= amount; return true; }
}
